// 主組件
const BedMonitor = () => {
  const leaveBedTimeSpanThreshold = parseInt(import.meta.env.VITE_LEAVE_BED_TOTAL_TIME, 10) || 180; //離床累及時間
  const fakeDataFrameRate = parseInt(import.meta.env.VITE_FAKE_DATA_HOLD_TIME, 10) || 5; //離床動畫frame時間
  let leaveBedThreshold = parseInt(import.meta.env.VITE_LEAVE_BED_THRESHOLD, 10) || 0.1; //離床累及時間
  if(leaveBedThreshold >= 1){
    leaveBedThreshold = 0.1;
  }
  
  let offLineSpan = 0;
  const [hasTriggerToggle, setHasTriggerToggle] = useState(false);
  const UEXT_sample_rawdata = [
    "/src/assets/icon_out-of-bed.jpg",
    "/src/assets/icon_leaving.jpg",
    "/src/assets/icon_sitting.jpg",
    "/src/assets/icon_resting.jpg",
    "/src/assets/icon_sitting.jpg",
    "/src/assets/icon_leaving.jpg",
  ];
  const getIconBasedOnPos = (pos) => {
    switch (pos) {
      case 1:
        return "/src/assets/icon_resting.jpg";
      case 2:
        return "/src/assets/icon_sitting.jpg";
      case 3:
        return "/src/assets/icon_leaving.jpg";
      case 4:
        return "/src/assets/icon_out-of-bed.jpg";
      default:
        return "/src/assets/icon_out-of-bed.jpg";
    }
  };

  const macaddressUEXT = import.meta.env.VITE_UEXT_MAC || "00C0CAB7A33D";
  const [rawdataUEXT, setRawdataUEXT] = useState("");
  const [widthUEXT, setWidthUEXT] = useState(12);
  const [heightUEXT, setHeightUEXT] = useState(20);
  const [uextImg, setUextImg] = useState(UEXT_sample_rawdata[0]);
  const [showTypeUEXT, setShowTypeUEXT] = useState("pressureImage");
  const [isOnlineUEXT, setOnlineUEXT] = useState(true);
  const [isAllowToggleUEXT, setAllowToggleUEXT] = useState(true);
  const [offlineTimeSpanUEXT, setOfflineTimeSpanUEXT] = useState(0);

  const sampleIndexUEXTRef = useRef(0); // Tracks which sample image to show
  const offlineCountUEXTRef = useRef(0); // Tracks the offline count for logic

  const toggleToOpenCV = () => {
    if (isOnlineUEXT && isAllowToggleUEXT)
      setShowTypeUEXT((prev) => (prev === "icon" ? "pressureImage" : "icon"));
  };

  const postUEXTData = async () => {
    try {
      const response = await fetch(`/api/8031/rawdata/${macaddressUEXT}`, {
        method: "GET",
        headers: { "Content-Type": "application/json" },
      });

      const contentType = response.headers.get("Content-Type");
      if (!response.ok || !contentType?.includes("application/json")) {
        throw new Error(`Expected JSON, got: ${contentType}`);
      }

      const data = await response.json();
      setWidthUEXT(data.WIDTH);
      setHeightUEXT(data.HEIGHT);
      if (data.STAT === 1) {
        setOnlineUEXT(true);
        offLineSpan = 0;
        console.log("(UEXT)POS: " + data.POS);
        // 2. CALCULATE NEXT STATUS USING LOCAL VARIABLES/REFS
        let nextTimeSpan = 0;
        if (data.POS === 4) {
          nextTimeSpan = offlineCountUEXTRef.current + 1;
        } else {
          nextTimeSpan = 0;
        }

        // Update Ref and State
        offlineCountUEXTRef.current = nextTimeSpan;
        setOfflineTimeSpanUEXT(nextTimeSpan);

        // 3. THE SWITCHING LOGIC YOU REQUESTED
        if (nextTimeSpan > leaveBedTimeSpanThreshold) {
          // OFFLINE MODE: Increment sample index and use sample data
          if (nextTimeSpan % fakeDataFrameRate === 0) {
            sampleIndexUEXTRef.current =
              (sampleIndexUEXTRef.current + 1) % UEXT_sample_rawdata.length;
            setUextImg(UEXT_sample_rawdata[sampleIndexUEXTRef.current]);
          }
          // Optional: Update UI mode if needed
          if (!hasTriggerToggle) {
            setShowTypeUEXT("icon");
            setHasTriggerToggle(true);
            setAllowToggleUEXT(false);
          }
        } else {
          // ONLINE MODE: Use the API
          sampleIndexUEXTRef.current = 0;
          setRawdataUEXT(data.IMAGE);
          setUextImg(getIconBasedOnPos(data.POS));
          setAllowToggleUEXT(true);
        }

        console.log("(UEXT)Leave count: " + nextTimeSpan);
      } else {
        setOnlineUEXT(false);
        if (offLineSpan % fakeDataFrameRate === 0) {
          sampleIndexUEXTRef.current =
            (sampleIndexUEXTRef.current + 1) % UEXT_sample_rawdata.length;
          setUextImg(UEXT_sample_rawdata[sampleIndexUEXTRef.current]);
        }
        offLineSpan++;
      }
    } catch (error) {
      console.error("(UEXT)Error making POST request:", error);
      setOnlineUEXT(false);
      setAllowToggleUEXT(false);
      if (offLineSpan % fakeDataFrameRate === 0) {
        sampleIndexUEXTRef.current =
          (sampleIndexUEXTRef.current + 1) % UEXT_sample_rawdata.length;
        setUextImg(UEXT_sample_rawdata[sampleIndexUEXTRef.current]);
      }
      offLineSpan++;
    }
    console.log("(UEXT)Offline count: " + offLineSpan);
  };

  useEffect(() => {
    // Initial call
    postUEXTData();

    // Set up interval
    const interval = setInterval(postUEXTData, 1000);

    // Clean up
    return () => clearInterval(interval);
  }, []);

  //UMAP
  const UMAP_sample_rawdata = [
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
  ];

  const macaddressUMAP = import.meta.env.VITE_UMAP_MAC || "00C0CAB7A36D";
  const [rawdataUMAP, setRawdataUMAP] = useState(UMAP_sample_rawdata[0]);
  const [widthUMAP, setWidthUMAP] = useState(25);
  const [heightUMAP, setHeightUMAP] = useState(63);
  const [showTypeUMAP, setShowTypeUMAP] = useState("pressureImage");
  const [isOnlineUMAP, setOnlineUMAP] = useState(true);
  const [offlineTimeSpanUMAP, setOfflineTimeSpanUMAP] = useState(0);

  const sampleIndexRef = useRef(0); // Tracks which sample image to show
  const offlineCountRef = useRef(0); // Tracks the offline count for logic

  const postUMAPData = async () => {
    try {
      const response = await fetch(`/api/8031/rawdata/${macaddressUMAP}`, {
        method: "GET",
        headers: { "Content-Type": "application/json" },
      });

      const contentType = response.headers.get("Content-Type");
      if (!response.ok || !contentType?.includes("application/json")) {
        throw new Error(`Expected JSON, got: ${contentType}`);
      }

      const data = await response.json();
      setWidthUMAP(data.WIDTH);
      setHeightUMAP(data.HEIGHT);
      if (data.STAT === 1) {
        setOnlineUMAP(true);
        // Calculate percentage
        let result = calculateZeroPercentage(data.IMAGE);
        console.log("(UMAP)Threshold: " + result);

        // 2. CALCULATE NEXT STATUS USING LOCAL VARIABLES/REFS
        let nextTimeSpan = 0;

        // Your specific logic: if result < 0.1, treat as offline
        if (result < leaveBedThreshold) {
          // Increment the Ref value
          nextTimeSpan = offlineCountRef.current + 1;
        } else {
          nextTimeSpan = 0;
        }

        // Update Ref and State
        offlineCountRef.current = nextTimeSpan;
        setOfflineTimeSpanUMAP(nextTimeSpan);

        // 3. THE SWITCHING LOGIC YOU REQUESTED
        if (nextTimeSpan > leaveBedTimeSpanThreshold) {
          // OFFLINE MODE: Increment sample index and use sample data
          sampleIndexRef.current =
            (sampleIndexRef.current + 1) % UMAP_sample_rawdata.length;
          setRawdataUMAP(UMAP_sample_rawdata[sampleIndexRef.current]);

          // Optional: Update UI mode if needed
          // setShowTypeUMAP("icon");
        } else {
          // ONLINE MODE: Use the API
          sampleIndexRef.current = 0;
          setRawdataUMAP(data.IMAGE);
        }
        console.log("(UMAP)Offline count: " + nextTimeSpan);
      } else {
        setOnlineUMAP(false);
        sampleIndexRef.current =
          (sampleIndexRef.current + 1) % UMAP_sample_rawdata.length;
        setRawdataUMAP(UMAP_sample_rawdata[sampleIndexRef.current]);
      }
    } catch (error) {
      console.error("(UMAP)Error making POST request:", error);
      sampleIndexRef.current =
        (sampleIndexRef.current + 1) % UMAP_sample_rawdata.length;
      setRawdataUMAP(UMAP_sample_rawdata[sampleIndexRef.current]);
      setOnlineUMAP(false);
    }
    // console.log("(UMAP)online status: " + isOnlineUMAP);
  };

  useEffect(() => {
    // Initial call
    postUMAPData();

    // Set up interval
    const interval = setInterval(postUMAPData, 1000);

    // Clean up
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="monitor-container">
      <MonitorUEXTCard
        type={showTypeUEXT}
        macaddress={macaddressUEXT}
        rawdata={rawdataUEXT}
        width={widthUEXT}
        height={heightUEXT}
        uextImg={uextImg}
        toggleToOpenCV={toggleToOpenCV}
        isOnline={isOnlineUEXT}
      />
      <MonitorUMAPCard
        type={showTypeUMAP}
        macaddress={macaddressUMAP}
        rawdata={rawdataUMAP}
        width={widthUMAP}
        height={heightUMAP}
        isOnline={isOnlineUMAP}
      />
    </div>
  );
};

export default BedMonitor;
